# Compare final unions for major interpretations
import pandas as pd, numpy as np
from scipy.stats import chi2
p='/app/dataset/synthetic_stroke_data.csv'
df=pd.read_csv(p); df['orig_index']=df.index
num=['age','bmi','avg_glucose_level']
noise=df.avg_glucose_level.lt(20)|df.avg_glucose_level.gt(800)|df.bmi.lt(10)|df.bmi.gt(60)|df.age.gt(120)
base=df.loc[~noise].copy()
mask_any=pd.Series(False,index=base.index)
bounds={}
for c in num:
 q1=base[c].quantile(.25); q3=base[c].quantile(.75); iqr=q3-q1; lo=q1-3*iqr; hi=q3+3*iqr
 bounds[c]=(lo,hi); mask_any|=base[c].lt(lo)|base[c].gt(hi)
gmask=base.avg_glucose_level.lt(bounds['avg_glucose_level'][0])|base.avg_glucose_level.gt(bounds['avg_glucose_level'][1])
protect_inc=[]; protect_exc=[]
for idx,r in base[gmask].iterrows():
 group=base[base.avg_glucose_level.eq(r.avg_glucose_level)]
 if group.stroke.mean()>=.5: protect_inc.append(idx)
 other=group[group.orig_index.ne(r.orig_index)]
 if len(other) and other.stroke.mean()>=.5: protect_exc.append(idx)
cat=(df.work_type.eq('children') & df.smoking_status.isin(['smokes','formerly smoked','smoker'])) | (df.work_type.eq('children') & df.age.gt(14)) | (df.work_type.eq('student') & df.age.le(3))

def final(protect, include_risk=True):
 iqr=mask_any.copy(); iqr.loc[protect]=False
 rem=base.loc[~iqr].copy()
 for c in num: rem[c+'_norm']=rem[c]/rem[c].max()
 rem['risk_proxy']=rem['age_norm']*rem['bmi_norm']*rem['avg_glucose_level_norm']
 vars=num+(['risk_proxy'] if include_risk else [])
 X=rem[vars].to_numpy(float); mu=X.mean(0); inv=np.linalg.pinv(np.cov(X,rowvar=False)); d=X-mu
 md2=np.einsum('ij,jk,ik->i',d,inv,d); thr=chi2.ppf(.99,df=len(vars))
