sets={
 'none_risk': final([],True),
 'inc_risk': final(protect_inc,True),
 'exc_risk': final(protect_exc,True),
 'none_noRisk': final([],False),
 'inc_noRisk': final(protect_inc,False),
}
for k,s in sets.items(): print(k,len(s))
keys=list(sets)
for i in range(len(keys)):
 for j in range(i+1,len(keys)):
  a,b=keys[i],keys[j]
  print('\n',a,'vs',b,'Jaccard',len(sets[a]&sets[b])/len(sets[a]|sets[b]),'only',a, sorted(sets[a]-sets[b])[:80], 'only',b, sorted(sets[b]-sets[a])[:80])
